import 'dart:math' as math;import 'package:cloud_firestore/cloud_firestore.dart';import 'package:flutter/material.dart';import 'package:geolocator/geolocator.dart';import '../chat/chat_screen.dart';class MarketplaceScreen extends StatefulWidget{const MarketplaceScreen({super.key});@override State<MarketplaceScreen> createState()=>_M();}class _M extends State<MarketplaceScreen>{Position? p;double radius=10;String q='';@override void initState(){super.initState();loc();}Future<void> loc()async{try{var z=await Geolocator.requestPermission();if(z==LocationPermission.denied||z==LocationPermission.deniedForever)return;p=await Geolocator.getCurrentPosition();if(mounted)setState((){});}catch(_){}}double km(double a,double b){if(p==null)return 0;const r=6371.0;final dl=(a-p!.latitude)*math.pi/180,dd=(b-p!.longitude)*math.pi/180;final h=math.sin(dl/2)*math.sin(dl/2)+math.cos(p!.latitude*math.pi/180)*math.cos(a*math.pi/180)*math.sin(dd/2)*math.sin(dd/2);return r*2*math.atan2(math.sqrt(h),math.sqrt(1-h));}@override Widget build(BuildContext c)=>Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(onChanged:(v)=>setState(()=>q=v.toLowerCase()),decoration:const InputDecoration(prefixIcon:Icon(Icons.search),hintText:'Cari barang...',border:OutlineInputBorder()))),Row(mainAxisAlignment:MainAxisAlignment.center,children:[const Icon(Icons.near_me),Text(p==null?' Lokasi belum aktif':' Radius '+radius.toStringAsFixed(0)+' km'),DropdownButton<double>(value:radius,items:[5,10,25,50,100].map((e)=>DropdownMenuItem(value:e.toDouble(),child:Text(e.toString()+' km'))).toList(),onChanged:(v)=>setState(()=>radius=v!))]),Expanded(child:StreamBuilder<QuerySnapshot>(stream:FirebaseFirestore.instance.collection('products').where('status',isEqualTo:'active').snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final a=s.data!.docs.where((d){final x=d.data() as Map<String,dynamic>;if(!(x['title']??'').toString().toLowerCase().contains(q))return false;return p==null||(x['latitude'] is num&&x['longitude'] is num&&km((x['latitude'] as num).toDouble(),(x['longitude'] as num).toDouble())<=radius);}).toList();if(a.isEmpty)return const Center(child:Text('Belum ada iklan di radius ini.'));return ListView.builder(itemCount:a.length,itemBuilder:(c,i){final d=a[i],x=d.data() as Map<String,dynamic>;final dis=p!=null&&x['latitude'] is num?km((x['latitude'] as num).toDouble(),(x['longitude'] as num).toDouble()):null;return Card(child:ListTile(leading:const Icon(Icons.inventory_2,size:40),title:Text(x['title']??''),subtitle:Text('Rp '+(x['price']??0).toString()+(dis==null?'':' • '+dis.toStringAsFixed(1)+' km')+'\n'+(x['description']??''),maxLines:2,overflow:TextOverflow.ellipsis),isThreeLine:true,trailing:IconButton(icon:const Icon(Icons.chat),onPressed:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ChatScreen(sellerId:x['sellerId']??'',sellerName:'Penjual',productId:d.id,productTitle:x['title']??'')))));});}))]);}}